using System.ComponentModel.DataAnnotations;

namespace DocSummary.Models;

public class SummarizeRequest
{
    [Required]
    [MinLength(1)]
    public string DocumentText { get; set; } = string.Empty;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public string Summary { get; set; } = string.Empty;
}

namespace DocSummary.Services;

public interface ISummarizationService
{
    string Summarize(string documentText);
}

namespace DocSummary.Services;

/// <summary>
/// Produces a concise summary by extracting the most important sentences
/// from the input document based on word-frequency scoring.
/// </summary>
public class ExtractiveSummarizationService : ISummarizationService
{
    private const int MaxSummarySentences = 3;

    private static readonly HashSet<string> StopWords = new(StringComparer.OrdinalIgnoreCase)
    {
        "a", "an", "the", "and", "or", "but", "is", "are", "was", "were",
        "in", "on", "at", "to", "for", "of", "with", "by", "it", "this",
        "that", "from", "as", "be", "been", "being", "have", "has", "had",
        "do", "does", "did", "will", "would", "could", "should", "may",
        "might", "shall", "can", "not", "no", "so", "if", "then", "than",
        "too", "very", "just", "about", "above", "after", "again", "all",
        "also", "am", "any", "because", "before", "between", "both",
        "each", "few", "he", "her", "here", "hers", "him", "his", "how",
        "i", "into", "its", "me", "more", "most", "my", "nor", "now",
        "only", "other", "our", "out", "over", "own", "s", "same", "she",
        "some", "such", "t", "their", "them", "there", "these", "they",
        "through", "under", "until", "up", "we", "what", "when", "where",
        "which", "while", "who", "whom", "why", "you", "your"
    };

    public string Summarize(string documentText)
    {
        var sentences = SplitIntoSentences(documentText);

        if (sentences.Count <= MaxSummarySentences)
            return string.Join(" ", sentences);

        var wordFrequencies = BuildWordFrequencies(sentences);
        var scored = ScoreSentences(sentences, wordFrequencies);

        // Pick top-scored sentences, preserving original order.
        var topIndices = scored
            .OrderByDescending(s => s.Score)
            .Take(MaxSummarySentences)
            .Select(s => s.Index)
            .OrderBy(i => i)
            .ToList();

        return string.Join(" ", topIndices.Select(i => sentences[i]));
    }

    private static List<string> SplitIntoSentences(string text)
    {
        return text
            .Split(['.', '!', '?'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(s => s.Length > 0)
            .Select(s => s + ".")
            .ToList();
    }

    private static Dictionary<string, int> BuildWordFrequencies(List<string> sentences)
    {
        var freq = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var sentence in sentences)
        {
            foreach (var word in Tokenize(sentence))
            {
                if (!StopWords.Contains(word))
                    freq[word] = freq.GetValueOrDefault(word) + 1;
            }
        }
        return freq;
    }

    private static List<(int Index, double Score)> ScoreSentences(
        List<string> sentences, Dictionary<string, int> wordFrequencies)
    {
        var scored = new List<(int Index, double Score)>();
        for (int i = 0; i < sentences.Count; i++)
        {
            var words = Tokenize(sentences[i]).Where(w => !StopWords.Contains(w)).ToList();
            double score = words.Count == 0
                ? 0
                : words.Sum(w => wordFrequencies.GetValueOrDefault(w)) / (double)words.Count;
            scored.Add((i, score));
        }
        return scored;
    }

    private static IEnumerable<string> Tokenize(string text)
    {
        return text.Split([' ', ',', ';', ':', '"', '\'', '(', ')', '[', ']', '\n', '\r', '\t'],
            StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
    }
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummarizeController : ControllerBase
{
    private readonly ISummarizationService _summarizationService;

